function SiteSearch({ onClose, returnFocus }) {
  const { lang, data } = useSite(), [query, setQuery] = useState('');
  const dialog = useRef(null);
  const modules = [
    { id:'module-agents', href:'/agents', category:'CCT INTELLIGENCE', title:'AI 智能体工作台', titleEn:'AI agent workspace', summary:'场景选择、任务编排、人工确认与执行简报', summaryEn:'Scenario selection, workflow planning, human gates and execution briefs' },
    { id:'module-think-tank', href:'/think-tank', category:'CCT KNOWLEDGE', title:'AI 智库', titleEn:'AI think tank', summary:'检索已发布知识、查看来源与证据边界', summaryEn:'Search published knowledge, sources and evidence boundaries' },
  ];
  const searchable = [...modules, ...(data?.content || []).map(item => ({ ...item, href:`/content/${encodeURIComponent(item.slug)}` }))];
  const matches = searchable.filter(item => !query.trim() || (value(item,'title',lang) + ' ' + value(item,'summary',lang) + ' ' + value(item,'category',lang)).toLowerCase().includes(query.trim().toLowerCase()));
  const items = matches.slice(0, 8);
  useEffect(() => { const previous = returnFocus.current; dialog.current?.showModal(); const overflow = document.body.style.overflow; document.body.style.overflow='hidden'; return () => { document.body.style.overflow=overflow; const target=previous?.isConnected && previous.getClientRects().length ? previous : document.querySelector('.site-search-trigger'); target?.focus(); }; }, []);
  return <dialog ref={dialog} className="site-search-dialog" aria-labelledby="site-search-title" onCancel={onClose} onClick={e=>{if(e.target===e.currentTarget)onClose();}}><div className="site-search-panel"><div className="site-search-panel-head"><h2 id="site-search-title">{copy(lang,'探索 CCT','Explore CCT')}</h2><button className="site-icon-button" onClick={onClose} aria-label={copy(lang,'关闭搜索','Close search')}><X size={22}/></button></div><label className="site-search site-search-large"><Search size={22}/><span className="site-sr-only">{copy(lang,'搜索产品、方案与洞察','Search products, solutions and insights')}</span><input autoFocus type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder={copy(lang,'搜索产品、方案与洞察…','Search products, solutions and insights…')}/></label><p className="site-search-hint" aria-live="polite">{query ? copy(lang,matches.length+' 项匹配 · 最多展示 8 项',matches.length+' matches · showing up to 8') : copy(lang,'从这些能力开始了解','Start with these capabilities')}</p><div className="site-search-results">{items.length ? items.map(item=><Link key={item.id} to={item.href} onClick={onClose}><span><small>{value(item,'category',lang) || 'CCT'}</small><strong>{value(item,'title',lang)}</strong></span><ArrowUpRight size={20}/></Link>) : <div className="site-empty"><Search size={28}/><p>{copy(lang,'没有找到相关内容，试试“智能体”或“AI”。','No results. Try “agents” or “AI”.')}</p><button className="site-reset" onClick={()=>setQuery('')}>{copy(lang,'清空搜索','Clear search')}</button></div>}</div><div className="site-search-keyboard">{copy(lang,'Tab 切换 · Enter 打开 · Esc 关闭','Tab to navigate · Enter to open · Esc to close')}</div></div></dialog>;
}

