function EvidenceBadge({ item }) {
  const { lang } = useSite();
  const label = item.claimScope === 'market' ? copy(lang, '市场数据', 'Market data') : item.claimScope === 'proposal' ? copy(lang, '方案方向', 'Solution direction') : copy(lang, '集团能力', 'Group capability');
  return <span className={cn('site-evidence-badge', `is-${item.claimScope || 'cct'}`)}><ShieldCheck size={12}/>{label}</span>;
}

function MarketSignalCard({ item, index }) {
  const { lang } = useSite();
  return <article className="site-signal-card"><div className="site-signal-top"><EvidenceBadge item={item}/></div><h3>{value(item, 'title', lang)}</h3><p>{value(item, 'summary', lang)}</p><div className="site-signal-source"><span>{item.sourceLabel}</span><time dateTime={item.sourceDate}>{formatDate(item.sourceDate, lang)}</time></div><div className="site-signal-actions"><Link to={`/content/${encodeURIComponent(item.slug)}`}>{copy(lang, '查看解读', 'Read analysis')}<ArrowRight size={15}/></Link>{item.sourceUrl && <a href={item.sourceUrl} target="_blank" rel="noreferrer">{copy(lang, '查看官方来源', 'Open official source')}<ExternalLink size={14}/></a>}</div></article>;
}

