function PageIntro({ eyebrow, title, description, children }) { const {lang}=useSite(); return <section className="site-page-intro site-container"><nav className="site-breadcrumb" aria-label={copy(lang,'面包屑导航','Breadcrumb')}><Link to="/">{copy(lang,'首页','Home')}</Link><ChevronRight size={13}/><span aria-current="page">{eyebrow}</span></nav><h1>{title}</h1><p>{description}</p>{children}</section>; }
function CollectionPage({ type }) {
  const { lang, data, loading } = useSite(), [category, setCategory] = useState('all'), [query, setQuery] = useState('');
  const items = (data?.content || []).filter(item => item.type === type && !(type === 'insight' && item.claimScope === 'market')), categories = [...new Set(items.map(item => item.category).filter(Boolean))];
  useEffect(() => { setCategory('all'); setQuery(''); }, [type]);
  const filtered = items.filter(item => (category === 'all' || item.category === category) && `${value(item, 'title', lang)} ${value(item, 'summary', lang)} ${value(item, 'body', lang)}`.toLowerCase().includes(query.toLowerCase()));
  const titles = {
    service: ['PRODUCT CAPABILITIES', '从推理底座，\n到业务执行。', 'From inference fabric\nto business execution.', '以单位任务成本、执行质量和治理边界组织生产级 AI 产品能力。', 'Production AI products organized around unit cost, execution quality and governance boundaries.'],
    solution: ['INDUSTRY SOLUTIONS', '让每一个场景，\n拥有智能的解法。', 'Intelligent answers\nfor real-world challenges.', '理解行业的业务逻辑，识别值得解决的问题，与团队共同建立从试点到规模化的路径。', 'Understand an industry’s logic, identify meaningful problems, and build a path from focused pilots to scale.'],
    insight: ['IDEAS & INSIGHTS', '看见变化，\n思考未来。', 'Observe change.\nThink forward.', '关于算力、人工智能与产业融合的持续思考。用清晰的观点，理解技术演进。', 'Perspectives on compute, artificial intelligence and industry. Clear thinking on technology as it evolves.']
  }[type];
  return <><PageIntro eyebrow={titles[0]} title={copy(lang, titles[1], titles[2])} description={copy(lang, titles[3], titles[4])}/><section className="site-container site-collection"><div className="site-collection-tools"><div className="site-filter-tabs" role="group" aria-label={copy(lang, '按分类筛选', 'Filter by category')}><button className={category === 'all' ? 'is-active' : ''} aria-pressed={category === 'all'} onClick={() => setCategory('all')}>{copy(lang, '全部', 'All')}<span>{items.length}</span></button>{categories.map(cat => <button key={cat} aria-pressed={category === cat} className={category === cat ? 'is-active' : ''} onClick={() => setCategory(cat)}>{value(items.find(item => item.category === cat), 'category', lang)}</button>)}</div><label className="site-search"><Search size={17}/><span className="site-sr-only">{copy(lang, '搜索内容', 'Search content')}</span><input value={query} onChange={e => setQuery(e.target.value)} placeholder={copy(lang, '搜索关键词', 'Search by keyword')} type="search"/></label></div><div className="site-result-bar"><p className="site-result-count" aria-live="polite">{copy(lang, `${filtered.length} 项内容`, `${filtered.length} ${filtered.length === 1 ? 'result' : 'results'}`)}</p>{(query || category!=='all') && <button className="site-reset" onClick={()=>{setQuery('');setCategory('all');}}><X size={14}/>{copy(lang,'重置筛选','Reset filters')}</button>}</div>{loading ? <Skeleton count={type === 'service' ? 4 : 3}/> : filtered.length ? <ContentCards items={filtered} type={type}/> : <EmptyState kind={query || category !== 'all' ? 'search' : 'content'}/>}</section>{type !== 'insight' && <section className="site-container site-process-strip"><SectionLabel number="→">{copy(lang, '我们的工作方式', 'HOW WE WORK')}</SectionLabel><div>{[['01', '理解需求', 'Discover', '共同识别问题与边界', 'Agree on the challenge and scope'], ['02', '验证价值', 'Validate', '用试点验证业务假设', 'Test the business case with a pilot'], ['03', '协同交付', 'Deliver', '明确责任与验收标准', 'Define ownership and acceptance'], ['04', '持续演进', 'Evolve', '根据反馈迭代和优化', 'Improve through measured feedback']].map(([n, zh, en, desc, descEn]) => <div key={n}><span>{n}</span><h3>{copy(lang, zh, en)}</h3><p>{copy(lang, desc, descEn)}</p></div>)}</div></section>}</>;
}
